// GlobalSettingsFixedPlanMax is the plan capacity every layout this build reads needs:
// the largest entry count over the identity plan and every lineage plan
// (mas-bandwidth/schema docs/FIXED-FORM-ALGORITHM.md §5.2). A plan slice of this length never
// refuses plan_too_large for a layout the lineage holds.
var GlobalSettingsFixedPlanMax = func() int32 {
	m := GlobalSettingsFixedPlan.Count
	for _, lane := range GlobalSettingsFixedLineagePlans {
		if lane.Count > m {
			m = lane.Count
		}
	}
	return m
}()

// A FILE: form byte, seven reserved zeros, the LAYOUT HASH at 8, body at 16,
// then the layout behind its u32 length, then the records to the end of it.
func GlobalSettingsFixedMeasure(count int64) int64 {
	return TableFixedHeaderBytes + 4 + int64(len(GlobalSettingsFixedLayout)) + count*GlobalSettingsFixedRecordBytes
}

// GlobalSettingsFixedSave is the fixed form's writer: it returns the bytes written, or -1 for a
// buffer too short or a value outside its declared contract (§3.1); see FixedSaveReason.
func GlobalSettingsFixedSave(values []GlobalSettings, buffer []byte) int64 {
	need := GlobalSettingsFixedMeasure(int64(len(values)))
	if int64(len(buffer)) < need {
		return -1
	}
	for k := range values {
		if !GlobalSettingsFixedCheckBody(&values[k]) {
			return -1
		}
	}
	clear(buffer[:TableFixedHeaderBytes])
	buffer[0] = TableFixedForm
	tableFixedPut64(buffer[TableFixedHashAt:], GlobalSettingsFixedHash)
	tableFixedPut32(buffer[TableFixedHeaderBytes:], uint32(len(GlobalSettingsFixedLayout)))
	copy(buffer[TableFixedHeaderBytes+4:], GlobalSettingsFixedLayout)
	at := buffer[TableFixedHeaderBytes+4+len(GlobalSettingsFixedLayout):]
	for k := range values {
		tableFixedPut64(at, GlobalSettingsFixedHash)
		clear(at[8 : 8+GlobalSettingsFixedBodyBytes])
		GlobalSettingsFixedWriteBody(at[8:], &values[k])
		at = at[GlobalSettingsFixedRecordBytes:]
	}
	return need
}

func GlobalSettingsFixedSaveReason(values []GlobalSettings, buffer []byte) (int64, error) {
	if n := GlobalSettingsFixedSave(values, buffer); n >= 0 {
		return n, nil
	}
	if int64(len(buffer)) < GlobalSettingsFixedMeasure(int64(len(values))) {
		return -1, TableRefuseTruncated
	}
	return -1, TableRefuseInvalidValue
}

// GlobalSettingsFixedLoad is the plain fixed-form read, and it is STRICT (mas-bandwidth/schema docs/SPEC-TABLES.md §6.5): -1 for
// every refusal of GlobalSettingsFixedLoadTolerant and for a read whose report.Err() is not nil, with
// every value it had written reset. A supplied report receives THIS read's report.
func GlobalSettingsFixedLoad(values []GlobalSettings, data []byte, plan []TableFixedEntry, report *TableReport) int64 {
	read := report
	if read == nil {
		read = &TableReport{}
	} else {
		*read = TableReport{}
	}
	n := GlobalSettingsFixedLoadTolerant(values, data, plan, read)
	if n < 0 {
		return -1
	}
	if read.Err() != nil {
		for k := range n {
			GlobalSettingsReset(&values[k])
		}
		return -1
	}
	return n
}

// GlobalSettingsFixedLoadTolerant is the TOLERANT fixed-form read (mas-bandwidth/schema docs/SPEC-TABLES.md §6.5): it keeps
// every recovered record, with the counters counted onto the report passed.
func GlobalSettingsFixedLoadTolerant(values []GlobalSettings, data []byte, plan []TableFixedEntry, report *TableReport) int64 {
	if report == nil {
		var local TableReport
		report = &local
	}
	*report = TableReport{}
	if len(data) < 1 {
		report.Malformed = true
		report.Reason = TableRefuseTruncated.Error()
		return -1
	}
	if data[0] != TableFixedForm {
		switch data[0] {
		case 1: // the VARIABLE form, and the only form this one is newer than
			return tableFixedRefuse(report, TableRefusePreviousForm.Error())
		case 2: // the MESSAGE form: a form this build carries, through another surface
			return tableFixedRefuse(report, TableRefuseMessageFormAsFile.Error())
		}
		return tableFixedRefuse(report, TableRefuseNewerForm.Error())
	}
	if len(data) < TableFixedHeaderBytes+4 {
		report.Malformed = true
		report.Reason = TableRefuseTruncated.Error()
		return -1
	}
	for _, reserved := range data[1:TableFixedHashAt] {
		if reserved != 0 {
			report.Malformed = true
			report.Reason = TableRefuseReservedNotZero.Error()
			return -1
		}
	}
	layoutBytes := tableFixedGet32(data[TableFixedHeaderBytes:])
	if int64(layoutBytes)+TableFixedHeaderBytes+4 > int64(len(data)) {
		return tableFixedRefuse(report, TableRefuseLayoutMalformed.Error())
	}
	layout := data[TableFixedHeaderBytes+4 : TableFixedHeaderBytes+4+layoutBytes]
	hash := tableFixedGet64(data[TableFixedHashAt:])
	pick := tableFixedSelect(GlobalSettingsFixedKnown, hash)
	if pick < 0 {
		return tableFixedRefuseHash(report, TableRefuseLayoutUnknown.Error(), hash)
	}
	if pick < GlobalSettingsFixedFloor {
		return tableFixedRefuseHash(report, TableRefuseLayoutUnsupported.Error(), hash)
	}
	known := &GlobalSettingsFixedKnown[pick]
	if int(layoutBytes) != len(known.Layout) {
		return tableFixedRefuse(report, TableRefuseLayoutMalformed.Error())
	}
	for i := range layout {
		if layout[i] != known.Layout[i] {
			return tableFixedRefuse(report, TableRefuseLayoutMalformed.Error())
		}
	}
	entries := GlobalSettingsFixedPlan.Entries
	entryCount := GlobalSettingsFixedPlan.Count
	// THE PREFILL'S HOLES ARE LAID ONCE (§4.3): the identity plan's list, then
	// a lineage plan's when an endpoint selects one. Nothing computes them per call.
	holes := GlobalSettingsFixedHoles
	recordBytes := known.Record
	censusUnknown, censusKind := int32(0), int32(0)
	if hash != GlobalSettingsFixedHash {
		lane := &GlobalSettingsFixedLineagePlans[pick]
		if lane.Why != "" {
			return tableFixedRefuse(report, lane.Why)
		}
		entries, entryCount = lane.Entries, lane.Count
		holes = GlobalSettingsFixedLineageHoles[pick]
		// THE CENSUS IS ONCE PER ENDPOINT and never per record (§5.4), and it
		// lands only on a read that returns: REFUSE moves no counter.
		censusUnknown, censusKind = lane.Unknown, lane.KindMismatch
	}
	if int64(entryCount) > int64(len(plan)) {
		return tableFixedRefuse(report, TableRefusePlanTooLarge.Error())
	}
	at := data[TableFixedHeaderBytes+4+layoutBytes:]
	rest := int64(len(data)) - TableFixedHeaderBytes - 4 - int64(layoutBytes)
	if recordBytes <= 8 || rest%recordBytes != 0 {
		report.Malformed = true
		report.Reason = TableRefuseTruncated.Error()
		return -1
	}
	n := rest / recordBytes
	if n > int64(len(values)) {
		return tableFixedRefuse(report, TableRefuseBatchTooLarge.Error())
	}
	defBytes := GlobalSettingsFixedResetImage
	for k, scan := int64(0), at; k < n; k, scan = k+1, scan[recordBytes:] {
		if tableFixedGet64(scan) != hash {
			return tableFixedRefuse(report, TableRefuseNoLayout.Error())
		}
		if why := tableFixedTextRefusal(entries, entryCount, scan[8:recordBytes]); why != "" {
			return tableFixedRefuse(report, why)
		}
	}
	for k := range n {
		dst := tableFixedOverlay(unsafe.Pointer(&values[k]), unsafe.Sizeof(values[k]))
		for i := range holes {
			h := holes[i]
			copy(dst[h.Off:h.Off+h.Size], defBytes[h.Off:h.Off+h.Size])
		}
		if why := tableFixedRun(entries, entryCount, at[8:recordBytes], dst, report); why != "" {
			return tableFixedRefuse(report, why)
		}
		if why := GlobalSettingsFixedFiniteBody(&values[k]); why != "" {
			for j := range k + 1 {
				GlobalSettingsReset(&values[j])
			}
			*report = TableReport{NonFiniteFloat: why}
			tableNonFiniteRefused(report)
			return -1
		}
		tableFixedForgedBounds(entries, entryCount, at[8:recordBytes], report)
		// AND THE BOUNDS THE LOOP DOES NOT HOLD, straight-line over the
		// storage it just wrote: the same pass for either plan (§3.4).
		GlobalSettingsFixedClamp(&values[k], report)
		at = at[recordBytes:]
	}
	report.Unknown += censusUnknown
	report.KindMismatch += censusKind
	return n
}

// THE READ-SIDE BOUNDS (mas-bandwidth/schema docs/SPEC-TABLES.md §3.4): a ranged scalar's
// declared min and max, and an ORDINAL's set — a union tag past the arm
// count, an enum ordinal past the enum's top value. Straight-line, after
// the copy, over STORAGE, so the identity plan and a plan compiled from a
// stranger's layout are held to the same numbers by the same pass. Every
// clamp COUNTS. The pass walks LIVE elements only: a counted array's live
// count, not its slack; an optional's payload only when present; a union's
// set arm, not the others.
func PackConfigFixedClamp(value *PackConfig, report *TableReport) {
	clamped := int32(0)
	PackConfigFixedClampBody(value, &clamped)
	report.Clamped += clamped
}

